from author_library import *
cards=[]
cards.append(compact('shan_si','单思','单思是单相的弟弟，家境富裕，本可不工作而生活舒适，却学了考古并成为盗墓高手。他并不像刻板印象中的书斋学者，常染浅蓝头发、在额角贴闪亮星星，以走在潮流前端的装束出入古墓。他具备历史、工程和器械方面的实际本领，同齐白等人一起把寻宝称作揭开人类遗产，行为本身仍包括偷取墓中物。一次误入藏着微小外星尸体的密室，让他对世界的理解骤然崩溃；他因震惊而酗酒，透露秘密，又被秘密机构盯上。齐白的朋友将他带到较安全的地方，他却仍去找卫斯理，认定对方藏着齐白交出的重要东西，激愤中拿玻璃摆设偷袭老朋友。后来他被灭口，死在卫斯理身边，所谓危险外星入侵者并不是凶手。终局卡恢复他最后生前人身，保留惊恐与被追杀的记忆，不把受害经历抹成全无道德责任，也不让一次失控掩盖他的聪明和求知欲。面对未知时，他最需要的是让真实证据重新连成可以承受的解释。','《盗墓》遭保密机构灭口；部署恢复最后生前人身，原已亡事实保留','主角','理解令自己恐惧的发现并找回安全感','外表时髦，实际具备严肃考古与探索知识','惊恐和误会叠加时会冲动逼问、伤及朋友，应保留结局教训','发现超出理解不等于世界必然灭亡，猜测必须与实际威胁分开',[ab('考古与盗墓','结合历史、工程和器械使用计划进入古墓','没有免疫机关或无限潜入能力，误认地点可带来严重后果'),ab('临时袭击','曾利用熟人疏于防备以摆设击昏卫斯理','是情境偷袭，不代表正面武术超过卫斯理')],[ev('056',24,41,'身份装束和专业背景'),ev('056',195,222,'激愤偷袭'),ev('056',3356,3359,'灭口行动来源'),ev('056',3816,3828,'受保护后仍行动与死亡')],profile='investigator',extra={'appearance':{'description':'时髦青年式装束，曾染浅蓝头发、额角贴金色星星。','portrayal':'平常斯文，受惊后情绪剧烈，不必每场都保持失控。'},'adaptations':[{'change':'恢复最后生前本人形态，保留遭灭口的经历知识。','reason':'原作已死亡。','power_impact':'不增加复活、不死或外星科技。'}]}))
cards.append(compact('tai_feng','泰丰将军','泰丰将军属于掌握外星事件秘密的军政高层，能够在严密警戒下安排卫斯理与白素转移、同最高领导层会面。他把未知文明的技术差距首先理解为无法抵御的威胁，一艘飞船造成大面积电力消失的事实，在他看来足以动摇国家乃至世界的秩序。这样的恐惧并非装腔作势，却同机构为保密采取的杀人灭口相连，让原本声称保护地球的目的变成伤害具体地球人的理由。与胡非尔相比，他在讨论中更能控制情绪，也愿意让外来者完整陈述，但仍希望通过宣传和幕后安排塑造大众对外星人的理解。最终他接受卫斯理去联络三名白袍来客的办法，等待会见未果，只能同意对方离开，要求一有消息立即联系。卡片保留他对秩序崩溃的担忧与官僚式调度，不把整支国家军队视作个人火力。年轻人系列另见泰来将军的名字，是否同人尚无确切对应，不能只因胡非尔在旁就强行合并；本卡仅按《盗墓》的泰丰建立。','《盗墓》仍在军政高层等待外星接触消息；与后作泰来将军是否同一人未确认','反派','防止未知技术冲击现存秩序，维持国家对情报的控制','以冷静命令安排戒备、转运和会谈，强调最坏后果','遇到无法抵抗的力量时优先保密并寻找中间联络人','担忧可以是真实的，所用手段仍须承担杀人和压制信息的责任',[ab('军事组织与保密调度','在真实授权下安排高警戒行动、情报处理及接触','没有个人对抗外星技术的能力；军力需具体国家支持')],[ev('056',3836,3856,'拘押后的转运与高层会谈'),ev('056',3885,3935,'技术差距与恐惧'),ev('056',3964,4002,'宣传安排、联络与放行')],profile='investigator',aliases=['泰丰'],extra={'uncertainties':['年轻人系列的泰来将军可能相关，但本卡未以相似职务和人际关系强并异名。']}))
cards.append(compact('white_robes','三名白袍外星访客','这三名外星访客以罩着长袍、仿佛没有身体的人形出现，令盗墓人的老练感官和人类普通判断同时失效。实际他们身形极小，约二十公分，头眼比例同人类差异很大，不能把空荡白袍误解为绝对无形。他们找盗墓界帮助，是为了取回同类遗体与飞船记录；地球方面却因秘密藏尸而杀人灭口，把来客先验地当作入侵者。卫斯理在接触中被他们跨洲转送，后来才知道所谓玻璃砖是一种记录载体，需要另一阅读装置。他们得知遗体接触纯氮已消失后接受事实，取回记录，决定离开不适合自己长期生活的地球。临走时，他们反复强调掠夺并不只由物质匮乏造成，精神空虚同样重要，显出与地球人不同的价值视角。终局卡以这三个无法分别命名的合作主体组记录，不将历史失事飞船的全套能力自动归入随身装备，也不把其拒绝解释的科技写成无边权柄。他们有优越技术，却未表现征服地球的意愿，冲突来自误解、取回遗物的坚持和对人类恐惧的疲惫。','《盗墓》得知同类遗体已消失，取回航行记录并离开地球','主角','取回同类相关遗物，完成任务后离开充满掠夺观念的环境','直接说明必要事项，对人类反复误解既无奈又不愿多作解释','被当成入侵者时说明生活环境差异，避免无意义争斗','未知技术不意味着无限能力；价值分歧也不能用物质丰裕单独解释',[ab('特殊空间转送','在接触过程中把卫斯理从北非转移到北美','依赖其文明技术，机制、频率和负载未明，不默认可对所有敌人无条件放逐'),ab('记录与阅读技术','用特殊载体保存航行日志，配合阅读仪转为人能理解的信息','缺少阅读仪时普通人不能读取，记录不能任意篡改现实'),ab('微小外星身体','真实身体藏在宽大外衣内，造成常规攻击和观察误判','并非没有身体；组成物接触纯氮发生解体，不赋予毒气免疫')],[ev('056',2020,2045,'白袍造成的误判'),ev('056',4032,4055,'真实大小、纯氮边界与离开'),ev('056',4067,4098,'价值观、记录机制及跨洲转送')],profile='ordinary',extra={'baseline':{'destruction':'未直接展示固定攻击威力；历史飞船造成区域停电不等于三个访客随身杀伤力。','durability':'微小外星肉体并非无形；纯氮接触可使其组成物溶入气体，其他抗性未知。','speed':'曾进行跨洲转送，属于条件未知的文明技术，非肉身奔跑速度。','energy':'具有高于当代地球的装置技术，能源储备和随身装备未完整交代。','stamina':'生理与技术续航未知，不作无限使用假设。'},'appearance':{'description':'约二十公分高，头眼比例很大，曾以宽长白袍伪装成人类大小外观。','portrayal':'声音生硬，三人共同出现，避免虚构固定领袖姓名。'}}))
rate(cards[-1],[1,4,2,3,7,3],neg=(2,3,2),tier='强',reason='跨洲转送和特殊信息技术有实证，但个人武器、持续输出及可重复范围不明；不计整艘历史飞船。',mastery='基本掌握')
save(cards)
